const items = $input.all();

const normalizedItems = items.map((item) => {
  const r = item.json;
  return {
    text: r.description || r.reviewText || r.content || r.body,
    title: r.title,
    rating: Number(r.score || r.rating || r.stars || r.ratingValue || 0),
    date: r.dateAndLocation || r.reviewDate || r.createdAt,
    productName: "",
    productAsin: r.productAsin || r.asin || "",
    productUrl: r.productLink || r.url || "",
  };
});

return normalizedItems;

// Build a colorful Sentiment Analysis report from many review items

function parseLLM(raw) {
  if (!raw) return { label: "Neutral", score: 0 };
  try { const o = typeof raw === "string" ? JSON.parse(raw) : raw; 
        return { label: o.label || "Neutral", score: Number(o.score)||0 }; }
  catch { return { label: "Neutral", score: 0 }; }
}
function normLabel(v){
  const s = String(v||"").toLowerCase();
  if (s.includes("pos")) return "Positive";
  if (s.includes("neg")) return "Negative";
  return "Neutral";
}
function cleanText(s){ return String(s||"").replace(/\s+/g," ").trim(); }
function bullets(arr, k){
  return arr.filter(r=>r.text).slice(0,k)
            .map(r=>cleanText(r.text).slice(0,220));
}

// --- collect reviews from incoming items
const reviews = items.map(it => {
  const j = it.json || {};
  const llmRaw = j.llm?.message?.content ?? j.message?.content ?? null;
  const { label, score } = llmRaw ? parseLLM(llmRaw)
                                  : { label: j.category ?? j.sentimentAnalysis?.category ?? "Neutral", score: 0 };
  return {
    text: cleanText(j.text),
    label: normLabel(label),
    score: Number(j.score ?? score) || 0,
    rating: (typeof j.rating === "number") ? j.rating : undefined,
    productName: cleanText(j.productName),
    productUrl: cleanText(j.productUrl)
  };
}).filter(r => r.text);

// --- aggregate
const N = reviews.length;
const counts = { Positive:0, Neutral:0, Negative:0 };
let sumScore = 0, sumRating = 0, nRating = 0;
for (const r of reviews){
  counts[r.label] = (counts[r.label]||0)+1;
  sumScore += r.score || 0;
  if (typeof r.rating === "number"){ sumRating += r.rating; nRating++; }
}
const pct = n => N ? ((n/N)*100).toFixed(0)+"%" : "0%";
const avgScore  = N ? (sumScore / N) : 0;
const avgRating = nRating ? (sumRating / nRating) : null;

// pick product info
const firstWithInfo = reviews.find(r=>r.productName || r.productUrl) || {};
const productName = firstWithInfo.productName || "";
const productUrl  = firstWithInfo.productUrl  || "";

// bullets
const posBul = bullets(reviews.filter(r=>r.label==="Positive"), 8);
const neuBul = bullets(reviews.filter(r=>r.label==="Neutral"), 4);
const negBul = bullets(reviews.filter(r=>r.label==="Negative"), 4);

// --- plain text
const lines = [];
lines.push("Sentiment Analysis Report");
if (productName) lines.push(`Product: ${productName}`);
if (productUrl)   lines.push(`URL: ${productUrl}`);
lines.push(`Out of ${N} reviews: ${counts.Positive} Positive, ${counts.Neutral} Neutral, ${counts.Negative} Negative.`);
lines.push(`Average score: ${avgScore.toFixed(2)}  |  Average rating: ${avgRating!==null?avgRating.toFixed(2):"N/A"}`);
const report_text = lines.join("\n");

// --- HTML (styled, PDF-friendly)
const esc = s=>s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
function section(title, color, arr){
  const lis = arr.length ? arr.map(t=>`<li>${esc(t)}</li>`).join("") : `<li>(none)</li>`;
  return `
    <h2 style="color:${color};margin:18px 0 6px 0;">${title}</h2>
    <ul style="margin:6px 0 14px 24px;">${lis}</ul>`;
}
const html = `
<!doctype html><html><head><meta charset="utf-8">
<title>Sentiment Analysis Report</title>
<style>
  body { font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial; margin: 28px; line-height: 1.45; }
  h1 { color:#15803d; margin:0 0 10px 0; font-size: 22px; }
  .muted{ color:#6b7280; font-size:12px; margin-top:24px; }
  .summary{ margin:8px 0 14px 0; }
  .k { font-weight:600; }
</style>
</head><body>
  <h1>📊 Sentiment Analysis Report</h1>
  ${productName ? `<div class="summary"><span class="k">Product:</span> ${esc(productName)}</div>` : ""}
  ${productUrl ? `<div class="summary"><span class="k">URL:</span> ${esc(productUrl)}</div>` : ""}
  <div class="summary">Out of <b>${N}</b> reviews: <b>${counts.Positive}</b> Positive, <b>${counts.Neutral}</b> Neutral, <b>${counts.Negative}</b> Negative.</div>
  <div class="summary">Average score: <b>${avgScore.toFixed(2)}</b> &nbsp;•&nbsp; Average rating: <b>${avgRating!==null?avgRating.toFixed(2):"N/A"}</b></div>

  ${section(`👍 Positive Reviews (${counts.Positive})`,"#16a34a", posBul)}
  ${section(`🙂 Neutral Reviews (${counts.Neutral})`,"#d97706", neuBul)}
  ${section(`👎 Negative Reviews (${counts.Negative})`,"#dc2626", negBul)}

  <div class="muted">Generated automatically via n8n 🚀</div>
</body></html>`.trim();

return [{ json: { report_html: html, report_text, counts, productName, productUrl } }];
